/* The shapes of the files the PlayStation game reads, without their contents (saturn_shapes.c, generated by
   saturn-re/tools/gen_shapes.py): saturn.c makes stand-ins of these shapes for what it cannot make from the
   Saturn's data yet. */
#ifndef PORT_SATURN_SHAPES_H
#define PORT_SATURN_SHAPES_H

#include <stddef.h>

enum { SHAPE_END, SHAPE_TIM, SHAPE_CMP, SHAPE_PRM, SHAPE_OBJECT, SHAPE_WAD, SHAPE_PART, SHAPE_VAG, SHAPE_RAW };

typedef struct Shape {
    int kind;
    int a;        /* a TIM's flags (15: an empty one of a sequence); an object's flags */
    int r1[4];    /* a TIM's palette rectangle; an object's vertex and normal counts */
    int r2[4];    /* a TIM's image rectangle; a VAG's sample rate */
    int count;    /* a sequence's TIMs, a model's objects, a wad's parts; a file's or a VAG's size */
    const struct Shape *list;
    const char *name;           /* an object's, a wad part's */
    const struct Shape *part;   /* a wad part's shape */
} Shape;

typedef struct ShapeFile {
    const char *path; /* as the game asks: \wipeout2\common\menu.dat */
    const Shape *shape;
} ShapeFile;

extern const ShapeFile saturnShapes[];

#endif
